sys_ui_action.script:
// bfd_ui_validate_entities — re-run entity validation and surface the result.
(function validateEntitiesAction() {
    var engine = new bfd_TriageEngine();
    var result = engine.validateEntities(current);
    var issues = result && result.issues ? result.issues : [];

    if (result && result.valid === true) {
        gs.addInfoMessage(
            'Entity validation passed: the customer, account and transaction on this case are present, active and consistent.'
        );
        engine.logAiDecision(current, {
            note: 'Agent ran entity validation — no issues found.',
            finalDecision: 'entity_validation_passed',
        });
    } else {
        gs.addErrorMessage('Entity validation failed with ' + issues.length + ' issue(s):');
        for (var i = 0; i < issues.length; i++) {
            gs.addErrorMessage('\u2022 ' + issues[i]);
        }
        engine.logAiDecision(current, {
            note: 'Agent ran entity validation — issues: ' + issues.join('; '),
            finalDecision: 'entity_validation_failed',
        });
    }

    current.update();
    action.setRedirectURL(current);
})();
